var PYPROG={ "rotate-trace": "TRACE_INPUT = {input}\nm = TRACE_INPUT['m']\nn = len(m)\nrot = [[m[n-1-j][i] for j in range(n)] for i in range(n)]  # 90 deg clockwise\nfor row in rot:\n    print(row)\n" };
