function frameSig(r){
  r.description="Signature line: the matrix as a deterministic protocol. In the Signature idiom a matrix is a sealed two-dimensional lane — rows and columns published, element (i,j) at a fixed address computed by a published layout formula, the same bytes in the same slots on every run. Where the public record below describes the conventional 2D array, the Signature edition pins its behavior: row-major addressing is exact, transpose and rotation are pure index remappings with no hidden copies, and every operation carries its exact cost in the open."+'\n\n'+r.description+'\n\n'+"That is the Signature line on matrices: the grid never shifts under you and the algebra is exact. The facts above are the standard facts — O(1) element access, O(n^3) naive multiplication, row-major layout — sealed inside a deterministic protocol so a transform computed once replays identically, everywhere.";
  return r;
}
function generate(seed,opts,rnd){
  opts=opts||{};rnd=rnd||prng(seed);
  if(seed>=1&&seed<=ARCHIVE.length){
    return JSON.parse(JSON.stringify(ARCHIVE[seed-1]));
  }
  var g=opts.group&&FIELDS.indexOf(opts.group)>=0?opts.group:null;
  var rec=rnd()<0.5?genComplexity(rnd,seed):genTrace(rnd,seed);
  if(g)rec.group=g;
  if(SIG)frameSig(rec);
  return rec;
}
function sjson(v){return JSON.stringify(v);}
function validate(r){
  var e=[];
  if(!r||typeof r!=='object')return {ok:false,errors:['not an object']};
  if(!new RegExp('^'+PREFIX.replace(/-/g,'\\-')+'\\d{6}$').test(r.id||''))e.push('id');
  if(FIELDS.indexOf(r.group)<0)e.push('group');
  if(typeof r.title!=='string'||!r.title.length)e.push('title');
  if(typeof r.description!=='string'||r.description.length<200)e.push('description');
  if(r.src!==GEN_SRC&&r.src!=='reference-authored'&&r.src!=='signature-line')e.push('src');
  if(r.method==='complexity-drill'){
    var hit=null;
    for(var i=0;i<OPS.length;i++)if(OPS[i][0]===r.answer.op)hit=OPS[i];
    if(!hit)e.push('unknown op');
    else if(r.answer.complexity!==hit[1])e.push('complexity mismatch');
  }else if(r.method&&EXEC[r.method]){
    var got;
    try{got=EXEC[r.method](r.test.input);}catch(x){e.push('exec threw');}
    if(got&&sjson(got)!==sjson(r.test.expected))e.push('trace mismatch');
  }else if(!r.method){
    if(!(r.ladder>=1&&r.ladder<=3))e.push('ladder');
  }else{
    e.push('method');
  }
  return {ok:!e.length,errors:e};
}
function driftCheck(rec,sample){
  var seen={};(sample||[]).forEach(function(s){if(s&&s.t)seen[s.t]=1;});
  if(rec&&seen[rec.title])return {ok:false,errors:['duplicate title in archive sample']};
  return {ok:true,errors:[]};
}
